def compare(a, b):
    """Returns -1, 0 or 1 as version a is older than, equal to or newer than b."""
    if a == b:
        return 0
    pa, pb = a.split("."), b.split(".")
    head_a, head_b = [int(x) for x in pa[:2]], [int(x) for x in pb[:2]]
    if head_a != head_b:
        return -1 if head_a < head_b else 1
    return -1 if pa[2:] < pb[2:] else 1

